import { useId } from 'react';
import './master-detail-dialog.css';

type Item = { id: string; name: string; summary: string; metadata: readonly { label: string; value: string }[] };
type Props = { open: boolean; items: readonly Item[]; selectedId: string; onSelect: (id: string) => void; onConfirm: (id: string) => void; onClose: () => void };

export function MasterDetailDialog({ open, items, selectedId, onSelect, onConfirm, onClose }: Props) {
  const uid = useId(); const selected = items.find(item => item.id === selectedId) ?? items[0];
  if (!open || !selected) return null;
  const titleId = `${uid}-title`, summaryId = `${uid}-summary`;
  return <div className="dialogBackdrop" onMouseDown={event => { if (event.target === event.currentTarget) onClose(); }}>
    <section className="masterDetailDialog" role="dialog" aria-modal="true" aria-labelledby={titleId} aria-describedby={summaryId} onKeyDown={event => { if (event.key === 'Escape') onClose(); }}>
      <header><div><h1 id={titleId}>Choose an item</h1><p id={summaryId}>Review its details before continuing.</p></div><button type="button" className="iconButton" aria-label="Close dialog" onClick={onClose}>×</button></header>
      <div className="dialogBody"><div className="masterList"><h2 id={`${uid}-items`}>Items</h2><ul aria-labelledby={`${uid}-items`}>{items.map(item => <li key={item.id}><button type="button" aria-current={item.id === selected.id ? 'true' : undefined} onClick={() => onSelect(item.id)}><strong>{item.name}</strong><span>{item.summary}</span></button></li>)}</ul></div>
        <article className="detailPane"><h2>{selected.name}</h2><p>{selected.summary}</p><dl>{selected.metadata.map(entry => <div key={entry.label}><dt>{entry.label}</dt><dd>{entry.value}</dd></div>)}</dl></article></div>
      <footer><button type="button" onClick={onClose}>Cancel</button><button type="button" className="primary" onClick={() => onConfirm(selected.id)}>Choose {selected.name}</button></footer>
    </section>
  </div>;
}

